sys_script_include.script:
var TripRequestBuddiesNameUtils = Class.create();
TripRequestBuddiesNameUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getBuddyInfo: function() {
        var tripId = this.getParameter('sysparm_trip_id');
        var result = {
            sys_id: '',
            name: ''
        };

        if (!tripId) {
            return JSON.stringify(result);
        }

        // Replace with your exact Trip Request table name
        var gr = new GlideRecord('x_travel_buddy_app_trip_request'); 
        if (gr.get(tripId)) {
            // Check assigned_to first, or u_buddy if assigned_to is empty
            var userGr = gr.assigned_to.getRefRecord();
            if (!userGr || !userGr.isValidRecord()) {
                userGr = gr.u_buddy.getRefRecord();
            }

            if (userGr && userGr.isValidRecord()) {
                result.sys_id = userGr.getUniqueValue();
                result.name = userGr.getDisplayValue();
            }
        }
        return JSON.stringify(result);
    },

    type: 'TripRequestBuddiesNameUtils'
});
